// Einmaliger Katch-up 2026-07-28: veroeffentlicht den kompletten Rueckstau bereits fertiger,
// aber noch nicht getooteter Vorgaenge in einem Rutsch (analog zum WordPress-Katch-up). Nutzt
// exakt dieselbe Filterlogik wie P9s 'Filter Mastodon-Kandidaten'. Vor diesem Lauf wurde bereits
// geprueft, dass keine der aktuell qualifizierenden Zeilen die Content-Vermischung (falscher
// Vorgang im Text) aus dem heutigen Vorfall aufweist - die 8 betroffenen Vorgaenge sind ueber
// den fehlenden wordpressGoslarPosted-Link ohnehin automatisch ausgeschlossen.
// LIMIT: leer lassen = kompletten Rueckstau nehmen, sonst Zahl eintragen zum Testen.
const LIMIT = 2;

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) { if (v === true) return true; if (typeof v === 'string') return v.trim().toLowerCase() === 'true'; return false; }
function parseDate(v) { const t = Date.parse(safeStr(v)); return Number.isFinite(t) ? t : Infinity; }

const candidates = items.filter(item => {
  const j = item.json || {};
  if (!safeStr(j.instagramCaption)) return false;
  if (safeBool(j.mastodonPosted)) return false;
  if (!safeStr(j.vorgangKey)) return false;
  if (safeStr(j.sharepicNeedStage) === 'topic_ok') {
    const hasImage = !!safeStr(j.imageFinalPath);
    const imageGivenUp = safeStr(j.imageStage) === 'topic_error_final';
    if (!hasImage && !imageGivenUp) return false;
  }
  if (!safeBool(j.wordpressGoslarPosted)) return false;
  if (!safeStr(j.wordpressGoslarPostLink)) return false;
  return true;
});

candidates.sort((a, b) => parseDate(a.json.lastAnalysisAt) - parseDate(b.json.lastAnalysisAt));

const selected = LIMIT ? candidates.slice(0, LIMIT) : candidates;
console.log(`[Mastodon-Backlog] ${selected.length} von ${candidates.length} Kandidaten ausgewaehlt.`);
return selected;

const now = Date.now();
const owner = `ALLRIS_Einmalig_Mastodon_Backlog_Publish:${$execution.id}`;
return items
  .filter(item => {
    const j = item.json || {};
    const oldOwner = String(j.claim_owner || '').trim();
    const expires = Date.parse(String(j.claim_expires_at || ''));
    return !oldOwner || !Number.isFinite(expires) || expires <= now;
  })
  .map(item => ({ json: {
    ...item.json,
    claimAction: 'acquire',
    claimOwner: owner,
    claimStage: 'publication',
    leaseMinutes: 30,
    expectedClaimOwner: item.json.claim_owner ?? null,
    expectedClaimExpiresAt: item.json.claim_expires_at ?? null
  } }));

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function parseArr(v) {
  try { const a = JSON.parse(v); return Array.isArray(a) ? a : []; } catch (e) { return []; }
}
function sanitizeTag(t) {
  return safeStr(t).replace(/^#/, '').replace(/[^\p{L}\p{N}_]/gu, '');
}
const MASTODON_CHAR_LIMIT = 800;
const MASTODON_URL_RESERVED_LENGTH = 23;
const FIXED_HASHTAGS = ['meingoslar', 'goslar', 'meinklüngelkannmehr', 'prioritätenproblem'];

const j = $json;
const caption = safeStr(j.instagramCaption) || safeStr(j.facebookPost);
const postLink = safeStr(j.wordpressGoslarPostLink);

const rawTags = parseArr(j.instagramHashtags).length ? parseArr(j.instagramHashtags) : parseArr(j.facebookHashtags);
const sanitized = rawTags.map(sanitizeTag).filter(Boolean);
const seen = new Set();
const tags = [];
for (const t of [...sanitized, ...FIXED_HASHTAGS]) {
  const key = t.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  tags.push('#' + t);
}
const hashtagLine = tags.join(' ');

const hashtagReserve = hashtagLine ? (2 + hashtagLine.length) : 0;
const linkReserve = postLink ? (2 + MASTODON_URL_RESERVED_LENGTH) : 0;
const bodyLimit = Math.max(0, MASTODON_CHAR_LIMIT - hashtagReserve - linkReserve);

let body = caption;
if (body.length > bodyLimit) {
  const cut = body.slice(0, Math.max(0, bodyLimit - 1));
  const lastBreak = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  body = (lastBreak > bodyLimit * 0.5 ? cut.slice(0, lastBreak + 1) : cut) + '…';
}

let tootText = body;
if (postLink) tootText += '\n\n' + postLink;
if (hashtagLine) tootText += '\n\n' + hashtagLine;

const hasImage = !!safeStr(j.imageFinalPath);

return { json: { ...j, tootText, hasImage } };

const original = $('Baue Toot-Text').itemMatching($itemIndex).json;
const uploadResult = $json || {};
return { json: { ...original, mastodonMediaId: uploadResult.id || null } };

const original = $('Baue Toot-Text').itemMatching($itemIndex).json;
const result = $json || {};
function extractErrorText(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') return String(v.message || v.description || v.error || JSON.stringify(v));
  return String(v);
}
return { json: {
  ...original,
  mastodonPostId: result.id || null,
  mastodonPostUrl: result.url || '',
  mastodonError: result.url ? '' : (extractErrorText(result.error) || extractErrorText(result.message) || 'Unbekannter Fehler beim Mastodon-Post')
} };

const vorgangKey = String($json.vorgangKey || '').trim();
const id = $json.id;
if (!vorgangKey || !id) return [];
return [{ json: { id, vorgangKey, claimAction: 'release', claimOwner: `ALLRIS_Einmalig_Mastodon_Backlog_Publish:${$execution.id}` } }];
